package com.autoops.common.security;import com.autoops.user.repository.UserRepository;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;@Component public class CurrentUser{private final UserRepository users;public CurrentUser(UserRepository u){users=u;}public Long id(){String name=SecurityContextHolder.getContext().getAuthentication().getName();return users.findByUsername(name).orElseThrow().getId();}}
